import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { format, subDays } from 'date-fns';

// 初始状态
const initialState = {
  totalPomodoros: 0,
  totalMinutes: 0,
  pomodoroHistory: {},
  lastSevenDays: {},
  streakData: {
    currentStreak: 0,
    longestStreak: 0,
    lastActiveDate: null
  }
};

// 创建slice
const statsSlice = createSlice({
  name: 'stats',
  initialState,
  reducers: {
    // 更新番茄历史记录
    updatePomodoroHistory: (state, action) => {
      const { date, taskId } = action.payload;
      
      // 如果这个日期不存在记录，初始化一个
      if (!state.pomodoroHistory[date]) {
        state.pomodoroHistory[date] = {
          count: 0,
          tasks: {}
        };
      }
      
      // 增加这个日期的番茄钟数量
      state.pomodoroHistory[date].count += 1;
      state.totalPomodoros += 1;
      
      // 如果有关联任务，记录任务相关的番茄钟
      if (taskId) {
        if (!state.pomodoroHistory[date].tasks[taskId]) {
          state.pomodoroHistory[date].tasks[taskId] = 0;
        }
        state.pomodoroHistory[date].tasks[taskId] += 1;
      }
      
      // 更新总专注时间（假设一个番茄钟25分钟）
      state.totalMinutes += 25;
    },
    
    // 计算连续工作天数
    calculateStreak: (state) => {
      const dates = Object.keys(state.pomodoroHistory)
        .sort((a, b) => new Date(a) - new Date(b));
        
      if (dates.length === 0) {
        return;
      }
      
      // 获取最近日期
      const lastDate = dates[dates.length - 1];
      const today = new Date().toISOString().split('T')[0];
      const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
      
      // 计算当前连续天数
      let currentStreak = 0;
      let i = dates.length - 1;
      
      // 如果最近一天是今天或昨天，开始计算连续天数
      if (lastDate === today || lastDate === yesterday) {
        let prevDate = new Date(dates[i]);
        currentStreak = 1;
        i--;
        
        while (i >= 0) {
          const currentDate = new Date(dates[i]);
          const diffTime = prevDate - currentDate;
          const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
          
          if (diffDays === 1) {
            currentStreak++;
            prevDate = currentDate;
          } else {
            break;
          }
          i--;
        }
      }
      
      // 更新最长连续天数
      state.streakData.currentStreak = currentStreak;
      state.streakData.lastActiveDate = lastDate;
      
      if (currentStreak > state.streakData.longestStreak) {
        state.streakData.longestStreak = currentStreak;
      }
    },
    
    // 计算最近七天的数据
    calculateLastSevenDays: (state) => {
      const lastSevenDays = {};
      const today = new Date();
      
      // 初始化最近七天的数据结构
      for (let i = 0; i < 7; i++) {
        const date = format(subDays(today, i), 'yyyy-MM-dd');
        lastSevenDays[date] = {
          count: 0,
          date
        };
      }
      
      // 填充实际数据
      for (const [date, data] of Object.entries(state.pomodoroHistory)) {
        if (lastSevenDays[date]) {
          lastSevenDays[date].count = data.count;
        }
      }
      
      state.lastSevenDays = lastSevenDays;
    },
    
    resetStats: (state) => {
      return initialState;
    }
  }
});

// 每次完成一个番茄钟时更新统计数据
export const recordCompletedPomodoro = createAsyncThunk(
  'stats/recordCompletedPomodoro',
  async (taskId, { getState, dispatch }) => {
    const state = getState();
    const date = new Date().toISOString().split('T')[0]; // 获取当前日期
    
    // 更新番茄钟历史记录
    // 注意：统计数据是实时更新的，每完成一个番茄钟就会更新一次
    dispatch(updatePomodoroHistory({ date, taskId }));
    
    // 重新计算连续记录和最近七天数据
    dispatch(calculateStreak());
    dispatch(calculateLastSevenDays());
    
    return { date };
  }
);

// 导出actions
export const { 
  updatePomodoroHistory, 
  calculateStreak, 
  calculateLastSevenDays, 
  resetStats 
} = statsSlice.actions;

// 选择器
export const selectProductivityByDay = (state) => {
  const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const productivityByDay = days.map(day => ({ day, count: 0 }));
  
  // 处理每个日期的数据
  Object.entries(state.stats.pomodoroHistory).forEach(([dateStr, data]) => {
    const date = new Date(dateStr);
    const dayOfWeek = date.getDay(); // 0 是周日, 1-6 是周一到周六
    productivityByDay[dayOfWeek].count += data.count;
  });
  
  return productivityByDay;
};

export const selectMostProductiveDay = (state) => {
  let mostProductive = { date: null, count: 0 };
  
  Object.entries(state.stats.pomodoroHistory).forEach(([date, data]) => {
    if (data.count > mostProductive.count) {
      mostProductive = { date, count: data.count };
    }
  });
  
  return mostProductive;
};

export default statsSlice.reducer;
